import math
import sqlite3
from dataclasses import dataclass
from datetime import datetime
from typing import Dict, List, Tuple, Optional

# ---- Fixed config (as required) ----
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


@dataclass
class BusinessRow:
    business_id: str
    name: str
    address: Optional[str]
    city: Optional[str]
    state: Optional[str]
    postal_code: Optional[str]
    latitude: Optional[float]
    longitude: Optional[float]
    stars: float
    review_count: int
    categories: Optional[str]


def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def fetch_candidates(city: str = "Clearwater", min_candidates: int = 10) -> List[BusinessRow]:
    """Fetch bagel-related candidate businesses; expand categories if too few."""
    conn = connect_sqlite(sqlite_paths["business"])
    cur = conn.cursor()

    base_sql = """
    SELECT business_id, name, address, city, state, postal_code, latitude, longitude, stars, review_count, categories
    FROM business
    WHERE city = ? AND is_open = 1
      AND (
        categories LIKE '%Bagel%' OR categories LIKE '%Bagels%'
      )
    """
    cur.execute(base_sql, (city,))
    rows = cur.fetchall()

    # If too few, broaden: Bakery/Deli/Breakfast & Brunch with later vector filtering.
    if len(rows) < min_candidates:
        broaden_sql = """
        SELECT business_id, name, address, city, state, postal_code, latitude, longitude, stars, review_count, categories
        FROM business
        WHERE city = ? AND is_open = 1
          AND (
            categories LIKE '%Bakery%' OR categories LIKE '%Delis%' OR categories LIKE '%Deli%'
            OR categories LIKE '%Breakfast%' OR categories LIKE '%Brunch%'
            OR categories LIKE '%Coffee%'
          )
        """
        cur.execute(broaden_sql, (city,))
        rows = cur.fetchall()

    conn.close()

    out = []
    for r in rows:
        out.append(
            BusinessRow(
                business_id=r["business_id"],
                name=r["name"],
                address=r.get("address"),
                city=r.get("city"),
                state=r.get("state"),
                postal_code=r.get("postal_code"),
                latitude=r.get("latitude"),
                longitude=r.get("longitude"),
                stars=float(r["stars"] or 0.0),
                review_count=int(r["review_count"] or 0),
                categories=r.get("categories"),
            )
        )
    return out


def _parse_checkin_dates(date_field: str) -> List[datetime]:
    """Yelp checkin.json typically stores a comma-separated list of timestamps."""
    if not date_field:
        return []
    parts = [p.strip() for p in date_field.split(",") if p.strip()]
    dts = []
    for p in parts:
        # Common formats: '2019-10-12 20:45:00'
        try:
            dts.append(datetime.fromisoformat(p))
        except Exception:
            # Try a fallback format
            try:
                dts.append(datetime.strptime(p, "%Y-%m-%d %H:%M:%S"))
            except Exception:
                continue
    return dts


def compute_sunday_morning_checkins(business_ids: List[str], start_hour: int = 7, end_hour: int = 12) -> Dict[str, int]:
    """Count checkins on Sundays between start_hour (inclusive) and end_hour (exclusive)."""
    if not business_ids:
        return {}

    conn = connect_sqlite(sqlite_paths["checkin"])
    cur = conn.cursor()

    # Chunk the IN clause to avoid SQLite variable limits
    counts: Dict[str, int] = {}
    chunk_size = 800
    for i in range(0, len(business_ids), chunk_size):
        chunk = business_ids[i:i+chunk_size]
        placeholders = ",".join(["?"] * len(chunk))
        sql = f"SELECT business_id, date FROM checkin WHERE business_id IN ({placeholders})"
        cur.execute(sql, chunk)
        for r in cur.fetchall():
            bid = r["business_id"]
            dates = _parse_checkin_dates(r["date"])
            c = 0
            for dt in dates:
                # Python weekday: Monday=0 ... Sunday=6
                if dt.weekday() == 6 and (start_hour <= dt.hour < end_hour):
                    c += 1
            counts[bid] = counts.get(bid, 0) + c

    conn.close()
    return counts


def try_vector_relevance(query_text: str, top_k: int = 50) -> Dict[str, Dict[str, float]]:
    """Query Milvus review/tip collections, aggregate to business_id.

    Returns:
      { business_id: { 'hit_count': int, 'best_score': float } }
    """
    try:
        from pymilvus import connections, Collection, utility
        from sentence_transformers import SentenceTransformer
    except Exception as e:
        print(f"[WARN] Milvus/vector dependencies not available: {e}")
        return {}

    try:
        connections.connect(alias="default", host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])
    except Exception as e:
        print(f"[WARN] Could not connect to Milvus: {e}")
        return {}

    model = None
    try:
        model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
    except Exception as e:
        print(f"[WARN] Could not load embedding model: {e}")
        return {}

    qvec = model.encode([query_text], normalize_embeddings=True)

    def agg_from_collection(coll_name: str) -> Dict[str, Dict[str, float]]:
        if not utility.has_collection(coll_name):
            return {}
        coll = Collection(coll_name)
        try:
            coll.load()
        except Exception:
            pass

        # Try to infer embedding field and id fields
        schema_fields = [f.name for f in coll.schema.fields]
        # Common embedding field names
        emb_field = None
        for cand in ["embedding", "vector", "emb", "review_embedding", "tip_embedding"]:
            if cand in schema_fields:
                emb_field = cand
                break
        if emb_field is None:
            # best-effort: pick first FLOAT_VECTOR field
            for f in coll.schema.fields:
                if str(f.dtype).endswith("FLOAT_VECTOR"):
                    emb_field = f.name
                    break
        if emb_field is None:
            print(f"[WARN] No vector field found in Milvus collection {coll_name}. Fields={schema_fields}")
            return {}

        output_fields = []
        for f in ["business_id", "review_id", "tip_id", "id"]:
            if f in schema_fields:
                output_fields.append(f)

        # Search params: IP works well with normalized embeddings; fallback to L2
        search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

        try:
            res = coll.search(
                data=qvec,
                anns_field=emb_field,
                param=search_params,
                limit=top_k,
                output_fields=output_fields
            )
        except Exception:
            # fallback
            search_params = {"metric_type": "L2", "params": {"nprobe": 16}}
            res = coll.search(
                data=qvec,
                anns_field=emb_field,
                param=search_params,
                limit=top_k,
                output_fields=output_fields
            )

        agg: Dict[str, Dict[str, float]] = {}

        # If we don't have business_id directly, try to map review_id -> business_id via SQLite review DB
        need_review_map = ("business_id" not in output_fields) and ("review_id" in output_fields)
        review_to_biz: Dict[str, str] = {}
        if need_review_map:
            conn_r = connect_sqlite(sqlite_paths["review"])
            cur_r = conn_r.cursor()
            review_ids = []
            for hit in res[0]:
                rid = getattr(hit.entity, "review_id", None)
                if rid:
                    review_ids.append(rid)
            # de-dup and chunk
            review_ids = list(dict.fromkeys(review_ids))
            for i in range(0, len(review_ids), 800):
                chunk = review_ids[i:i+800]
                placeholders = ",".join(["?"] * len(chunk))
                sql = f"SELECT review_id, business_id FROM review WHERE review_id IN ({placeholders})"
                try:
                    cur_r.execute(sql, chunk)
                    for rr in cur_r.fetchall():
                        review_to_biz[rr["review_id"]] = rr["business_id"]
                except Exception:
                    break
            conn_r.close()

        for hit in res[0]:
            score = float(hit.distance)  # for IP larger is better; for L2 smaller is better (but still usable as a signal)
            bid = None
            if "business_id" in output_fields:
                bid = getattr(hit.entity, "business_id", None)
            elif "review_id" in output_fields:
                rid = getattr(hit.entity, "review_id", None)
                bid = review_to_biz.get(rid)

            if not bid:
                continue

            if bid not in agg:
                agg[bid] = {"hit_count": 0.0, "best_score": score}
            agg[bid]["hit_count"] += 1.0
            agg[bid]["best_score"] = max(agg[bid]["best_score"], score)

        return agg

    agg_reviews = agg_from_collection(milvus_config['milvus_collections']['reviews'])
    agg_tips = agg_from_collection(milvus_config['milvus_collections']['tips'])

    # Merge
    merged: Dict[str, Dict[str, float]] = {}
    for d in [agg_reviews, agg_tips]:
        for bid, v in d.items():
            if bid not in merged:
                merged[bid] = {"hit_count": 0.0, "best_score": v.get("best_score", 0.0)}
            merged[bid]["hit_count"] += float(v.get("hit_count", 0.0))
            merged[bid]["best_score"] = max(merged[bid]["best_score"], float(v.get("best_score", 0.0)))

    return merged


def try_graph_candidates(city: str = "Clearwater") -> Dict[str, Dict[str, str]]:
    """Optional: pull extra candidates/enrichment from Neo4j."""
    try:
        from neo4j import GraphDatabase
    except Exception as e:
        print(f"[WARN] Neo4j driver not available: {e}")
        return {}

    try:
        driver = GraphDatabase.driver(neo4j_config['neo4j_uri'], auth=neo4j_config['neo4j_auth'])
    except Exception as e:
        print(f"[WARN] Could not connect to Neo4j: {e}")
        return {}

    cypher = """
    MATCH (c:City {name:$city})<-[:IN_CITY]-(b:Business)-[:IN_CATEGORY]->(cat:Category)
    WHERE toLower(cat.name) CONTAINS 'bagel'
    RETURN b.business_id AS business_id, b.name AS name, cat.name AS category
    LIMIT 200
    """

    out: Dict[str, Dict[str, str]] = {}
    try:
        with driver.session() as session:
            rs = session.run(cypher, city=city)
            for r in rs:
                bid = r.get("business_id")
                if bid:
                    out[bid] = {
                        "name": r.get("name") or "",
                        "category": r.get("category") or ""
                    }
    except Exception as e:
        print(f"[WARN] Neo4j query failed: {e}")
    finally:
        driver.close()

    return out


def normalize_dict(d: Dict[str, float]) -> Dict[str, float]:
    if not d:
        return {}
    vals = list(d.values())
    mn, mx = min(vals), max(vals)
    if mx == mn:
        return {k: 0.0 for k in d}
    return {k: (v - mn) / (mx - mn) for k, v in d.items()}


def recommend_best_bagels_clearwater(top_n: int = 5) -> List[Dict]:
    city = "Clearwater"
    query_text = "best bagels sunday morning clearwater"

    candidates = fetch_candidates(city=city)
    cand_ids = [c.business_id for c in candidates]

    # Checkins signal
    checkins = compute_sunday_morning_checkins(cand_ids, start_hour=7, end_hour=12)

    # Vector relevance signal
    vec_rel = try_vector_relevance(query_text=query_text, top_k=50)

    # Optional graph enrichment
    graph_info = try_graph_candidates(city=city)

    # Build score components
    stars_map = {c.business_id: c.stars for c in candidates}
    rc_map = {c.business_id: c.review_count for c in candidates}
    chk_map = {bid: float(checkins.get(bid, 0)) for bid in cand_ids}
    vec_hit_map = {bid: float(vec_rel.get(bid, {}).get("hit_count", 0.0)) for bid in cand_ids}

    # Normalize
    stars_n = normalize_dict(stars_map)
    rc_n = normalize_dict({k: math.log1p(v) for k, v in rc_map.items()})
    chk_n = normalize_dict(chk_map)
    vec_n = normalize_dict(vec_hit_map)

    # Weighted score
    w_stars, w_rc, w_chk, w_vec = 0.45, 0.20, 0.25, 0.10

    results = []
    for c in candidates:
        bid = c.business_id
        score = (
            w_stars * stars_n.get(bid, 0.0) +
            w_rc * rc_n.get(bid, 0.0) +
            w_chk * chk_n.get(bid, 0.0) +
            w_vec * vec_n.get(bid, 0.0)
        )

        results.append({
            "business_id": bid,
            "name": c.name,
            "address": c.address,
            "city": c.city,
            "state": c.state,
            "postal_code": c.postal_code,
            "stars": c.stars,
            "review_count": c.review_count,
            "categories": c.categories,
            "sunday_morning_checkins": int(checkins.get(bid, 0)),
            "vector_hit_count": float(vec_rel.get(bid, {}).get("hit_count", 0.0)),
            "vector_best_score": float(vec_rel.get(bid, {}).get("best_score", 0.0)),
            "graph_category": graph_info.get(bid, {}).get("category", ""),
            "final_score": float(score)
        })

    results.sort(key=lambda x: x["final_score"], reverse=True)
    return results[:top_n]


if __name__ == "__main__":
    try:
        top = recommend_best_bagels_clearwater(top_n=5)
        print("Top places for bagels on Sunday morning in Clearwater (ranked):\n")
        for i, r in enumerate(top, 1):
            line1 = f"{i}. {r['name']}  |  {r['stars']:.1f}★  ({r['review_count']} reviews)"
            addr = ", ".join([p for p in [r.get('address'), r.get('city'), r.get('state'), r.get('postal_code')] if p])
            line2 = f"   Address: {addr}" if addr else "   Address: (n/a)"
            line3 = f"   Sunday morning checkins(7-12): {r['sunday_morning_checkins']} | Vector hits: {r['vector_hit_count']:.0f}"
            if r.get("graph_category"):
                line3 += f" | Graph category: {r['graph_category']}"
            line4 = f"   Categories: {r.get('categories') or ''}"
            print("\n".join([line1, line2, line3, line4]))
            print()

    except Exception as e:
        print(f"[ERROR] Failed to generate recommendations: {e}")

