import json
import ast
import sqlite3
from typing import Dict, Any, List, Tuple

import numpy as np

from pymilvus import connections, Collection

# ---- 1) Fixed configuration (as required) ----
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

MILVUS_CONF = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

NEO4J_CONF = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# ---- 2) Utilities ----
def safe_parse_attributes(attr_val: Any) -> Dict[str, Any]:
    """Parse Yelp 'attributes' which is often a stringified dict, sometimes None.
    Returns a dict.
    """
    if attr_val is None:
        return {}
    if isinstance(attr_val, dict):
        return attr_val
    if isinstance(attr_val, (bytes, bytearray)):
        attr_val = attr_val.decode('utf-8', errors='ignore')
    if not isinstance(attr_val, str):
        return {}

    s = attr_val.strip()
    if not s or s.lower() == 'none':
        return {}

    # Yelp exports often look like: "{'RestaurantsPriceRange2': '2', 'Ambience': '{"romantic": true, ...}', ...}"
    # so we try literal_eval first; then try JSON.
    try:
        d = ast.literal_eval(s)
        if isinstance(d, dict):
            # parse nested dict-like strings (Ambience, GoodForMeal, etc.)
            for k, v in list(d.items()):
                if isinstance(v, str) and v.strip().startswith('{') and v.strip().endswith('}'):
                    try:
                        d[k] = ast.literal_eval(v)
                    except Exception:
                        try:
                            d[k] = json.loads(v)
                        except Exception:
                            pass
            return d
    except Exception:
        pass

    try:
        d = json.loads(s)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def get_milvus_fields(col: Collection) -> Tuple[str, str]:
    """Return (primary_key_field, vector_field) by inspecting schema.
    Works even if field names are not known upfront.
    """
    pk_field = None
    vec_field = None
    for f in col.schema.fields:
        if getattr(f, 'is_primary', False):
            pk_field = f.name
        # vector dtype name differs by pymilvus versions; check attribute or repr
        if 'VECTOR' in str(f.dtype).upper():
            vec_field = f.name
    if pk_field is None or vec_field is None:
        raise RuntimeError(f"Could not infer PK/vector fields for collection {col.name}.")
    return pk_field, vec_field


def embed_query(text: str) -> List[float]:
    """Create embedding for query using sentence-transformers.
    NOTE: This assumes the same/similar embedding model used when building Milvus vectors.
    """
    try:
        from sentence_transformers import SentenceTransformer
    except Exception as e:
        raise RuntimeError(
            "sentence-transformers is required. Install via: pip install sentence-transformers"
        ) from e

    model_name = "sentence-transformers/all-MiniLM-L6-v2"
    model = SentenceTransformer(model_name)
    vec = model.encode([text], normalize_embeddings=True)[0]
    return vec.astype(np.float32).tolist()


def sql_in_clause_params(items: List[Any]) -> str:
    return "(" + ",".join(["?"] * len(items)) + ")


# ---- 3) Main retrieval pipeline ----
def find_romantic_quiet_restaurants(
    query_text: str = "romantic candlelight dinner atmosphere, private and quiet, intimate date night",
    topk_milvus: int = 200,
    final_topn: int = 5
) -> List[Dict[str, Any]]:

    # 3.1 Connect Milvus
    connections.connect(alias="default", host=MILVUS_CONF['milvus_host'], port=MILVUS_CONF['milvus_port'])

    review_col_name = MILVUS_CONF['milvus_collections']['reviews']
    col = Collection(review_col_name)
    col.load()

    pk_field, vec_field = get_milvus_fields(col)

    qvec = embed_query(query_text)

    # 3.2 Vector search in Milvus (reviews)
    # Use COSINE if available; otherwise Milvus might store IP/L2. We set COSINE by default.
    search_params = {
        "metric_type": "COSINE",
        "params": {"nprobe": 16}
    }

    results = col.search(
        data=[qvec],
        anns_field=vec_field,
        param=search_params,
        limit=topk_milvus,
        output_fields=[]
    )

    hits = results[0]
    review_ids = [h.entity.get(pk_field) if hasattr(h, 'entity') else h.id for h in hits]
    # similarity for COSINE: higher is better in many setups; pymilvus returns distance depending metric.
    # We'll keep raw score and treat higher as better for COSINE/IP, lower is better for L2.
    raw_scores = [float(h.score) for h in hits]

    if not review_ids:
        return []

    # 3.3 Map review_id -> business_id via SQLite (review.db)
    con_review = sqlite3.connect(sqlite_paths['review'])
    con_review.row_factory = sqlite3.Row

    # Chunk to avoid SQLite variable limits
    mapped_reviews = []
    chunk = 900
    for i in range(0, len(review_ids), chunk):
        part = review_ids[i:i+chunk]
        q = f"SELECT review_id, business_id, text, stars, date FROM review WHERE review_id IN {sql_in_clause_params(part)}"
        rows = con_review.execute(q, part).fetchall()
        mapped_reviews.extend(rows)

    con_review.close()

    # Index score by review_id
    score_by_review = {rid: s for rid, s in zip(review_ids, raw_scores)}

    # 3.4 Aggregate to business candidates
    business_agg: Dict[str, Dict[str, Any]] = {}
    for r in mapped_reviews:
        rid = r['review_id']
        bid = r['business_id']
        if not bid:
            continue
        s = score_by_review.get(rid, 0.0)
        entry = business_agg.setdefault(bid, {
            'business_id': bid,
            'semantic_score_sum': 0.0,
            'hit_count': 0,
            'evidence_reviews': []
        })
        entry['semantic_score_sum'] += s
        entry['hit_count'] += 1
        # Keep a few evidence snippets
        if len(entry['evidence_reviews']) < 3 and r['text']:
            snippet = r['text'].replace('
', ' ')[:240]
            entry['evidence_reviews'].append({
                'review_id': rid,
                'review_stars': r['stars'],
                'date': r['date'],
                'snippet': snippet
            })

    candidate_bids = list(business_agg.keys())
    if not candidate_bids:
        return []

    # 3.5 Fetch business metadata and filter to restaurants/open
    con_bus = sqlite3.connect(sqlite_paths['business'])
    con_bus.row_factory = sqlite3.Row

    businesses = []
    for i in range(0, len(candidate_bids), chunk):
        part = candidate_bids[i:i+chunk]
        q = (
            f"SELECT business_id, name, address, city, state, postal_code, stars, review_count, categories, attributes, is_open "
            f"FROM business "
            f"WHERE business_id IN {sql_in_clause_params(part)} "
            f"AND is_open = 1 "
            f"AND categories LIKE '%Restaurants%'"
        )
        rows = con_bus.execute(q, part).fetchall()
        businesses.extend(rows)

    con_bus.close()

    # 3.6 Attribute-based soft scoring (romantic/intimate + quiet)
    def bonus_from_attributes(attr: Dict[str, Any]) -> float:
        bonus = 0.0
        ambience = attr.get('Ambience')
        if isinstance(ambience, str):
            # sometimes it is a string like "{'romantic': True, ...}"
            try:
                ambience = ast.literal_eval(ambience)
            except Exception:
                ambience = None

        if isinstance(ambience, dict):
            if ambience.get('romantic') is True:
                bonus += 1.0
            if ambience.get('intimate') is True:
                bonus += 0.7
            if ambience.get('classy') is True:
                bonus += 0.2

        noise = attr.get('NoiseLevel')
        # Yelp sometimes stores 'u'quiet'' or 'quiet'
        if isinstance(noise, str):
            n = noise.strip().strip('u'"').strip('"'')
            if n == 'quiet':
                bonus += 0.8
            elif n == 'average':
                bonus += 0.2
        return bonus

    final = []
    for b in businesses:
        bid = b['business_id']
        agg = business_agg.get(bid)
        if not agg:
            continue
        attrs = safe_parse_attributes(b['attributes'])
        attr_bonus = bonus_from_attributes(attrs)

        # Popularity/quality priors (lightweight)
        stars = float(b['stars'] or 0.0)
        review_count = int(b['review_count'] or 0)
        popularity_bonus = min(np.log1p(review_count) / 10.0, 0.5)  # cap

        score = agg['semantic_score_sum'] + attr_bonus + popularity_bonus + (stars - 3.5) * 0.1

        final.append({
            'business_id': bid,
            'name': b['name'],
            'address': b['address'],
            'city': b['city'],
            'state': b['state'],
            'postal_code': b['postal_code'],
            'stars': stars,
            'review_count': review_count,
            'categories': b['categories'],
            'attributes_parsed': {
                'Ambience': attrs.get('Ambience'),
                'NoiseLevel': attrs.get('NoiseLevel')
            },
            'hit_count': agg['hit_count'],
            'evidence_reviews': agg['evidence_reviews'],
            'score': float(score)
        })

    final.sort(key=lambda x: x['score'], reverse=True)
    return final[:final_topn]


