def safe_parse_attributes(attr_val: Any) -> Dict[str, Any]:
    """Parse Yelp 'attributes' which is often stored as a stringified dict.
    Returns {} if missing/unparseable.
    """
    if attr_val is None:
        return {}
    if isinstance(attr_val, dict):
        return attr_val
    if isinstance(attr_val, str):
        s = attr_val.strip()
        if not s:
            return {}
        # Try python-literal dict first (common in Yelp dumps)
        try:
            return ast.literal_eval(s)
        except Exception:
            # Some pipelines store JSON; try JSON as fallback
            try:
                import json
                return json.loads(s)
            except Exception:
                return {}
    return {}


def truthy(v: Any) -> bool:
    if isinstance(v, bool):
        return v
    if v is None:
        return False
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        return v.strip().lower() in {"true", "1", "yes", "y"}
    return False


def get_collection_vector_dim(col: Collection) -> int:
    schema = col.schema
    for f in schema.fields:
        # Vector field types in pymilvus: DataType.FLOAT_VECTOR / BINARY_VECTOR
        if str(f.dtype).endswith("FLOAT_VECTOR") or str(f.dtype).endswith("BINARY_VECTOR"):
            # For float vector, params has dim
            return int(f.params.get("dim"))
    raise RuntimeError(f"No vector field found in collection {col.name}")


def build_text_embedder(target_dim: int):
    """Return a callable embed(text)->List[float] that matches target_dim.

    Strategy:
    1) Try CLIP text encoder via open_clip (dims often 512/768)
    2) Fallback to SentenceTransformer (dims often 384/768)

    If none matches target_dim, raise with a clear error.
    """
    # Try open_clip
    try:
        import torch
        import open_clip

        # Common CLIP model dims: ViT-B-32 -> 512, ViT-L-14 -> 768
        candidates = [
            ("ViT-B-32", "openai"),
            ("ViT-L-14", "openai"),
        ]

        for model_name, pretrained in candidates:
            model, _, _ = open_clip.create_model_and_transforms(model_name, pretrained=pretrained)
            tokenizer = open_clip.get_tokenizer(model_name)
            model.eval()
            # Determine dim
            with torch.no_grad():
                tokens = tokenizer(["dim probe"])
                feat = model.encode_text(tokens)
                dim = int(feat.shape[-1])
            if dim == target_dim:
                def embed(text: str) -> List[float]:
                    with torch.no_grad():
                        t = tokenizer([text])
                        x = model.encode_text(t).float()
                        x = x / x.norm(dim=-1, keepdim=True)
                        return x[0].cpu().tolist()
                return embed
    except Exception:
        pass

    # Try sentence-transformers
    try:
        from sentence_transformers import SentenceTransformer
        # Try a couple common models
        for name in ["all-MiniLM-L6-v2", "all-mpnet-base-v2"]:
            model = SentenceTransformer(name)
            dim = int(model.get_sentence_embedding_dimension())
            if dim == target_dim:
                def embed(text: str) -> List[float]:
                    v = model.encode([text], normalize_embeddings=True)
                    return v[0].tolist()
                return embed
    except Exception:
        pass

    raise RuntimeError(
        f"Cannot build an embedder with dim={target_dim}. "
        f"Install open_clip_torch/torch or sentence-transformers, or ensure Milvus vector dim matches an available model."
    )


def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def main():
    city = "Clearwater"

    # -----------------------------
    # Step 1: SQL filter restaurants in Clearwater with OutdoorSeating
    # -----------------------------
    biz_conn = connect_sqlite(sqlite_paths["business"])

    sql = """
    SELECT business_id, name, address, city, state, stars, review_count, categories, attributes
    FROM business
    WHERE city = ?
      AND categories LIKE '%Restaurant%'
    """

    rows = biz_conn.execute(sql, (city,)).fetchall()

    candidate_businesses: Dict[str, Dict[str, Any]] = {}
    for r in rows:
        attrs = safe_parse_attributes(r["attributes"])
        outdoor = truthy(attrs.get("OutdoorSeating"))
        if outdoor:
            candidate_businesses[r["business_id"]] = {
                "business_id": r["business_id"],
                "name": r["name"],
                "address": r["address"],
                "city": r["city"],
                "state": r["state"],
                "stars": r["stars"],
                "review_count": r["review_count"],
                "categories": r["categories"],
                "outdoor_seating": True,
                "raw_attributes": attrs,
            }

    if not candidate_businesses:
        print(f"No restaurant candidates with OutdoorSeating found in {city}.")
        return

    # -----------------------------
    # Step 2: Milvus photo_vector search for 'romantic city night view'
    # -----------------------------
    connections.connect(alias="default", host=milvus_host, port=milvus_port)

    photo_col_name = milvus_collections["photos"]
    if not utility.has_collection(photo_col_name):
        raise RuntimeError(f"Milvus collection not found: {photo_col_name}")

    photo_col = Collection(photo_col_name)
    photo_col.load()

    photo_dim = get_collection_vector_dim(photo_col)
    embed_photo_text = build_text_embedder(photo_dim)

    photo_query = "romantic city night view restaurant patio outdoor seating city lights"
    qv = [embed_photo_text(photo_query)]

    # Try to identify likely vector field name; assume first vector field in schema
    vector_field = None
    for f in photo_col.schema.fields:
        if str(f.dtype).endswith("FLOAT_VECTOR"):
            vector_field = f.name
            break
    if vector_field is None:
        raise RuntimeError("No FLOAT_VECTOR field found in photo collection schema")

    # Try to include output fields commonly present
    output_fields = []
    for fname in ["photo_id", "business_id"]:
        if any(f.name == fname for f in photo_col.schema.fields):
            output_fields.append(fname)

    search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

    # Some deployments use COSINE; IP works if vectors normalized.
    res = photo_col.search(
        data=qv,
        anns_field=vector_field,
        param=search_params,
        limit=200,
        output_fields=output_fields
    )

    # Map photo hits to businesses. If business_id not stored in Milvus, resolve via SQLite photo table.
    photo_conn = connect_sqlite(sqlite_paths["photo"])

    # Collect hits
    hits = res[0]
    hit_records: List[Tuple[str, float, str]] = []  # (photo_id, score, business_id_or_empty)
    photo_ids: List[str] = []

    for h in hits:
        ent = getattr(h, "entity", None)
        score = float(h.score)
        pid = None
        bid = ""
        if ent is not None:
            if "photo_id" in output_fields:
                pid = ent.get("photo_id")
            # some milvus versions allow direct dict-like
            if pid is None and hasattr(h, "id"):
                pid = str(h.id)
            if "business_id" in output_fields:
                bid = ent.get("business_id") or ""
        else:
            pid = str(getattr(h, "id", ""))
        if not pid:
            continue
        photo_ids.append(pid)
        hit_records.append((pid, score, bid))

    business_by_photo: Dict[str, str] = {}
    if any(bid for _, _, bid in hit_records):
        for pid, _, bid in hit_records:
            if bid:
                business_by_photo[pid] = bid
    else:
        # Resolve from SQLite photo table
        if photo_ids:
            # Chunk to avoid SQLite parameter limits
            for i in range(0, len(photo_ids), 800):
                chunk = photo_ids[i:i+800]
                qmarks = ",".join(["?"] * len(chunk))
                q = f"SELECT photo_id, business_id FROM photo WHERE photo_id IN ({qmarks})"
                for r in photo_conn.execute(q, chunk).fetchall():
                    business_by_photo[r["photo_id"]] = r["business_id"]

    # Aggregate per business
    photo_hits_by_business: Dict[str, Dict[str, Any]] = {}
    for pid, score, bid0 in hit_records:
        bid = bid0 or business_by_photo.get(pid)
        if not bid:
            continue
        if bid not in candidate_businesses:
            continue  # enforce Clearwater+Restaurant+OutdoorSeating
        d = photo_hits_by_business.setdefault(bid, {"best_photo_score": -1e9, "photo_ids": []})
        d["photo_ids"].append(pid)
        if score > d["best_photo_score"]:
            d["best_photo_score"] = score

    if not photo_hits_by_business:
        print("No matching 'romantic city night view' photo evidence found for OutdoorSeating restaurants in Clearwater.")
        return

    # -----------------------------
    # Step 3 (optional): Milvus reviews search for supporting evidence
    # -----------------------------
    review_hits_by_business: Dict[str, float] = {}
    reviews_col_name = milvus_collections["reviews"]
    if utility.has_collection(reviews_col_name):
        try:
            reviews_col = Collection(reviews_col_name)
            reviews_col.load()
            rev_dim = get_collection_vector_dim(reviews_col)
            embed_review_text = build_text_embedder(rev_dim)

            # Find vector field
            rev_vector_field = None
            for f in reviews_col.schema.fields:
                if str(f.dtype).endswith("FLOAT_VECTOR"):
                    rev_vector_field = f.name
                    break

            rev_output_fields = []
            for fname in ["business_id", "review_id"]:
                if any(f.name == fname for f in reviews_col.schema.fields):
                    rev_output_fields.append(fname)

            rev_query = "romantic night view city lights patio outdoor seating"
            rv = [embed_review_text(rev_query)]
            rev_search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

            rev_res = reviews_col.search(
                data=rv,
                anns_field=rev_vector_field,
                param=rev_search_params,
                limit=200,
                output_fields=rev_output_fields
            )

            for h in rev_res[0]:
                ent = getattr(h, "entity", None)
                if ent is None or "business_id" not in rev_output_fields:
                    continue
                bid = ent.get("business_id")
                if not bid or bid not in candidate_businesses:
                    continue
                score = float(h.score)
                if (bid not in review_hits_by_business) or (score > review_hits_by_business[bid]):
                    review_hits_by_business[bid] = score
        except Exception:
            # Non-fatal: still can answer using photos
            review_hits_by_business = {}

    # -----------------------------
    # Step 4: Merge & rank
    # -----------------------------
    results = []
    for bid, ph in photo_hits_by_business.items():
        biz = candidate_businesses[bid]
        best_photo_score = ph["best_photo_score"]
        photo_count = len(ph["photo_ids"])
        best_review_score = review_hits_by_business.get(bid, None)

        # Simple scoring heuristic
        score = best_photo_score + 0.15 * (photo_count ** 0.5)
        if best_review_score is not None:
            score += 0.35 * best_review_score

        results.append({
            **biz,
            "match_score": score,
            "best_photo_score": best_photo_score,
            "photo_hit_count": photo_count,
            "sample_photo_ids": ph["photo_ids"][:5],
            "best_review_score": best_review_score,
        })

    results.sort(key=lambda x: x["match_score"], reverse=True)

    # Print top N
    top_n = 10
    print(f"Top {min(top_n, len(results))} OutdoorSeating restaurants in {city} with romantic city night view evidence:\n")
    for i, r in enumerate(results[:top_n], 1):
        print(f"{i}. {r['name']}  | {r['stars']}★ ({r['review_count']} reviews)")
        print(f"   Address: {r['address']}, {r['city']}, {r['state']}")
        print(f"   Photo evidence: best_score={r['best_photo_score']:.4f}, hits={r['photo_hit_count']}, sample_photo_ids={r['sample_photo_ids']}")
        if r["best_review_score"] is not None:
            print(f"   Review evidence: best_score={r['best_review_score']:.4f}")
        print(f"   Categories: {r['categories']}")
        print()


